func (q offeringQueue) History(ctx context.Context, filter requestreview.QueueFilter) ([]requestreview.Row, *requestreview.Cursor, error) {
	items, cursor, err := q.query.ListHistory(ctx, careQueueFilter(filter))
	if err != nil {
		return nil, nil, err
	}
	rows := make([]requestreview.Row, 0, len(items))
	for _, item := range items {
		row := item.Request
		rows = append(rows, requestreview.Row{Type: requestreview.TypeOffering, SortTime: row.UpdatedAt, ID: row.ID, StudentID: row.StudentID, StudentName: item.StudentName, SubmittedBy: row.SubmittedBy, Status: row.Status, Version: excusedrequests.ParentRequestVersion(row.UpdatedAt), DecidedAt: requestreview.HistoryDecidedAt(row.ReviewedAt, row.UpdatedAt), Data: ToOfferingRequestHistoryResponse(item)})
	}
	return rows, careQueueCursor(cursor), nil
}

func (q offeringQueue) OpenCount(ctx context.Context, today requestreview.Date) (int, error) {
